/** Tiny dependency-free bundler for this project's local ES modules.
 * It intentionally supports only the syntax used in this repository:
 * relative named imports plus named class/function/const/export-list exports.
 * Keeping this fallback in-tree lets START.bat builds work even when npm dev
 * dependencies have not been installed on a new machine.
 */
import fs from 'node:fs';
import path from 'node:path';

const root = path.resolve(new URL('..', import.meta.url).pathname);
const entry = path.join(root, 'app.js');
const output = path.join(root, 'game.bundle.js');
const seen = new Map();
const order = [];

function id(file) {
  return '__mod_' + path.relative(root, file).replace(/\.js$/i, '').replace(/[^a-z0-9_]+/gi, '_');
}
function resolve(from, spec) {
  if (!spec.startsWith('.')) throw new Error(`Only local imports are supported: ${spec}`);
  const file = path.resolve(path.dirname(from), spec);
  if (!file.startsWith(root + path.sep)) throw new Error(`Import escapes project root: ${spec}`);
  return file;
}
function scan(file) {
  if (seen.has(file)) return;
  const source = fs.readFileSync(file, 'utf8');
  const imports = [...source.matchAll(/^import\s*\{([\s\S]*?)\}\s*from\s*["']([^"']+)["'];?\s*$/gm)]
    .map(match => ({ full: match[0], bindings: match[1].trim(), spec: match[2], file: resolve(file, match[2]) }));
  seen.set(file, { source, imports });
  for (const item of imports) scan(item.file);
  order.push(file);
}
function transform(file) {
  const record = seen.get(file);
  let source = record.source;
  for (const item of record.imports) source = source.replace(item.full, `const { ${item.bindings.replace(/\s+/g, ' ')} } = ${id(item.file)};`);
  const exports = new Set();
  source = source.replace(/^export\s+(class|function|const|let|var)\s+([A-Za-z_$][\w$]*)/gm, (_, kind, name) => {
    exports.add(name); return `${kind} ${name}`;
  });
  source = source.replace(/export\s*\{([\s\S]*?)\};?/gm, (_, list) => {
    for (const raw of list.split(',')) {
      const part = raw.trim(); if (!part) continue;
      const match = part.match(/^([A-Za-z_$][\w$]*)(?:\s+as\s+([A-Za-z_$][\w$]*))?$/);
      if (!match) throw new Error(`Unsupported export in ${file}: ${part}`);
      exports.add(match[2] || match[1]);
    }
    return '';
  });
  if (/\bexport\s+default\b/.test(source)) throw new Error(`Default exports are unsupported: ${file}`);
  const returnLine = exports.size ? `\nreturn { ${[...exports].join(', ')} };` : '\nreturn {};';
  return `const ${id(file)} = (() => {\n${source}${returnLine}\n})();\n`;
}

scan(entry);
const body = order.map(transform).join('\n');
fs.writeFileSync(output, `// Generated by tools/simple-bundle.mjs. Do not edit directly.\n(() => {\n'use strict';\n${body}\n})();\n`);
console.log(`Bundled ${order.length} modules -> ${path.relative(root, output)} (${fs.statSync(output).size} bytes)`);
